"""Write lib/design/cat/figure_data.dart from traced.json."""
import json, base64, struct, sys
d=json.load(open('traced.json'))
CLS=['plug','base','shade','deep','light','ink']
def enc(vals): return base64.b64encode(struct.pack('<%dh'%len(vals),*vals)).decode()
def q(v): return max(-32768,min(32767,int(round(v*1000))))
lines=["// GENERATED by tool/cat_trace/trace.py from design/cat_sheets/*.webp.",
"// Do not edit by hand: change the drawings or the tracer and run it again.",
"// ignore_for_file: lines_longer_than_80_chars","",
"part of 'cat.dart';","",
"/// One drawn pose, traced: where the head sits (eye midpoint, tilt), the",
"/// tail's root, and the body as tone layers. Units are the head's half",
"/// width; the origin is the floor under the figure.",
"class TracedPose {",
"  const TracedPose(this.head, this.tilt, this.root, this.layers, this.morph);",
"  final Offset head;",
"  final double tilt;",
"  final Offset? root;",
"  /// Base64 of little-endian int16: per layer its class index and contour",
"  /// count, per contour its point count and x, y, tail weight (×1000).",
"  final String layers;",
"  /// The body outline resampled to the same number of points in every pose,",
"  /// for morphing: x, y, tail weight (×1000).",
"  final String morph;",
"}","",
"/// Layer classes in [TracedPose.layers], in painting order.",
"const tracedClasses = %s;" % json.dumps(CLS).replace('"',"'"),"",
"const tracedSheets = <String, List<TracedPose>>{"]
for name,poses in d.items():
    lines.append(f"  '{name}': [")
    for p in poses:
        vals=[]
        layers=[(CLS.index(c),v) for c,v in p['layers'].items() if v]
        layers.sort()
        vals.append(len(layers))
        for ci,cs in layers:
            vals += [ci,len(cs)]
            for c in cs:
                vals.append(len(c['p']))
                for (x,y),w in zip(c['p'],c['w']): vals += [q(x),q(y),q(w)]
        mv=[]
        for (x,y),w in zip(p['morph'],p['morphW']): mv += [q(x),q(y),q(w)]
        hx,hy,ang=p['head']; rt=p['root']
        root='null' if rt is None else f'Offset({rt[0]:.3f}, {rt[1]:.3f})'
        lines.append(f"    TracedPose(Offset({hx:.3f}, {hy:.3f}), {ang:.3f}, {root}, '{enc(vals)}', '{enc(mv)}'),")
    lines.append("  ],")
lines.append("};")
open(sys.argv[1],'w').write('\n'.join(lines)+'\n')
